const commerceUnsubscribesSince = `-- name: CommerceUnsubscribesSince :many
SELECT DISTINCT ON (sc.id) sc.id, sc.external_id, sc.contact_id, ce.occurred_at
FROM consent_events ce
JOIN store_customers sc ON sc.contact_id = ce.contact_id AND sc.store_id = $1
WHERE ce.action = 'unsubscribed' AND ce.occurred_at > $2 AND ce.occurred_at <= $3
  AND (ce.list_id = $4 OR ce.list_id IS NULL OR ce.source IN ('one_click', 'unsubscribe_page'))
  AND ce.source NOT LIKE 'store:%'
  AND sc.marketing = 'subscribed'
ORDER BY sc.id, ce.occurred_at DESC
`

type CommerceUnsubscribesSinceParams struct {
	StoreID uuid.UUID  `json:"storeId"`
	Since   time.Time  `json:"since"`
	Until   time.Time  `json:"until"`
	ListID  *uuid.UUID `json:"listId"`
}

type CommerceUnsubscribesSinceRow struct {
	ID         uuid.UUID  `json:"id"`
	ExternalID string     `json:"externalId"`
	ContactID  *uuid.UUID `json:"contactId"`
	OccurredAt time.Time  `json:"occurredAt"`
}

// Contacts who left the store's list, or every list, since a time: the
// unsubscribes to tell the store about (write-back). Leaving that the
// store itself caused (source store:…) is left out.
func (q *Queries) CommerceUnsubscribesSince(ctx context.Context, arg CommerceUnsubscribesSinceParams) ([]CommerceUnsubscribesSinceRow, error) {
	rows, err := q.db.Query(ctx, commerceUnsubscribesSince,
		arg.StoreID,
		arg.Since,
		arg.Until,
		arg.ListID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CommerceUnsubscribesSinceRow{}
	for rows.Next() {
		var i CommerceUnsubscribesSinceRow
		if err := rows.Scan(
			&i.ID,
			&i.ExternalID,
			&i.ContactID,
			&i.OccurredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

