const commerceWorkspaceRevenue = `-- name: CommerceWorkspaceRevenue :one
SELECT count(*)::bigint AS orders, coalesce(sum(o.total_cents - o.refunded_cents), 0)::bigint AS revenue,
    count(*) FILTER (WHERE o.matched <> 'none')::bigint AS credited,
    coalesce(sum(o.total_cents - o.refunded_cents) FILTER (WHERE o.matched <> 'none'), 0)::bigint AS credited_revenue,
    coalesce(max(o.currency), '')::text AS currency
FROM store_orders o JOIN stores s ON s.id = o.store_id
WHERE o.workspace_id = $1 AND o.placed_at >= $2 AND o.placed_at <= $3 AND NOT o.test AND NOT o.cancelled
`

type CommerceWorkspaceRevenueParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	Since       time.Time `json:"since"`
	Until       time.Time `json:"until"`
}

type CommerceWorkspaceRevenueRow struct {
	Orders          int64  `json:"orders"`
	Revenue         int64  `json:"revenue"`
	Credited        int64  `json:"credited"`
	CreditedRevenue int64  `json:"creditedRevenue"`
	Currency        string `json:"currency"`
}

// Every connected store's orders and credited revenue in a period (the
// Earn overview's card).
func (q *Queries) CommerceWorkspaceRevenue(ctx context.Context, arg CommerceWorkspaceRevenueParams) (CommerceWorkspaceRevenueRow, error) {
	row := q.db.QueryRow(ctx, commerceWorkspaceRevenue, arg.WorkspaceID, arg.Since, arg.Until)
	var i CommerceWorkspaceRevenueRow
	err := row.Scan(
		&i.Orders,
		&i.Revenue,
		&i.Credited,
		&i.CreditedRevenue,
		&i.Currency,
	)
	return i, err
}
